56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /**
66	     * A pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
67	     * and a dotted domain. Deliberately conservative so obviously malformed values (e.g. a bare
68	     * word with no {@code @}) are rejected while ordinary addresses are accepted.
69	     */
70	    private static final Pattern EMAIL_PATTERN =
71	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    public OwnerRestControllerV1(ClinicService clinicService,
82	                                 OwnerMapper ownerMapper,
83	                                 PetMapper petMapper,
84	                                 VisitMapper visitMapper) {
85	        this.clinicService = clinicService;
86	        this.ownerMapper = ownerMapper;
87	        this.petMapper = petMapper;
88	        this.visitMapper = visitMapper;
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        List<String> missingFields = new ArrayList<>();
120	        if (isBlank(ownerFieldsDto.getFirstName())) {
121	            missingFields.add("firstName");
122	        }
123	        if (isBlank(ownerFieldsDto.getLastName())) {
124	            missingFields.add("lastName");
125	        }
126	        if (isBlank(ownerFieldsDto.getAddress())) {
127	            missingFields.add("address");
128	        }
129	        if (isBlank(ownerFieldsDto.getCity())) {
130	            missingFields.add("city");
131	        }
132	        if (isBlank(ownerFieldsDto.getTelephone())) {
133	            missingFields.add("telephone");
134	        }
135	        if (!missingFields.isEmpty()) {
136	            throw new MissingOwnerFieldsException(missingFields);
137	        }
138	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
139	            String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
140	            String address = normalizeHousehold(ownerFieldsDto.getAddress());
141	            boolean householdInUse = this.clinicService.findAllOwners().stream()
142	                .anyMatch(existing -> lastName.equals(normalizeHousehold(existing.getLastName()))
143	                    && address.equals(normalizeHousehold(existing.getAddress())));
144	            if (householdInUse) {
145	                throw new DuplicateHouseholdException(
146	                    "an owner with the same last name and address already exists");
147	            }
148	        }
149	        String telephone = toE164(ownerFieldsDto.getTelephone());
150	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
151	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
152	        if (telephoneInUse) {
153	            throw new DuplicateTelephoneException(
154	                "an owner with the same E.164 telephone already exists");
155	        }
156	        ownerFieldsDto.setTelephone(telephone);
157	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
158	        HttpHeaders headers = new HttpHeaders();
159	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
160	        if (owner.getRegistrationDate() == null) {
161	            owner.setRegistrationDate(LocalDate.now());
162	        }
163	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
164	        this.clinicService.saveOwner(owner);
165	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
166	        headers.setLocation(UriComponentsBuilder.newInstance()
167	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
168	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Override
173	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
174	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
175	        if (currentOwner == null) {
176	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
177	        }
178	        currentOwner.setAddress(ownerFieldsDto.getAddress());
179	        currentOwner.setCity(ownerFieldsDto.getCity());
180	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
181	        currentOwner.setLastName(ownerFieldsDto.getLastName());
182	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
183	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
184	        this.clinicService.saveOwner(currentOwner);
185	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Transactional
190	    @Override
191	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
192	        Owner owner = this.clinicService.findOwnerById(ownerId);
193	        if (owner == null) {
194	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
195	        }
196	        this.clinicService.deleteOwner(owner);
197	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
198	    }
199	
200	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
201	    @Override
202	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
203	        Owner owner = this.clinicService.findOwnerById(ownerId);
204	        if (owner == null) {
205	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
206	        }
207	        HttpHeaders headers = new HttpHeaders();
208	        Pet pet = petMapper.toPet(petFieldsDto);
209	        owner.setId(ownerId);
210	        pet.setOwner(owner);
211	        pet.getType().setName(null);
212	        this.clinicService.savePet(pet);
213	        PetDto petDto = petMapper.toPetDto(pet);
214	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
215	            .buildAndExpand(pet.getId()).toUri());
216	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
217	    }
218	
219	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
220	    @Override
221	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
222	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
223	        if (currentOwner != null) {
224	            Pet currentPet = this.clinicService.findPetById(petId);
225	            if (currentPet != null) {
226	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
227	                currentPet.setName(petFieldsDto.getName());
228	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
229	                this.clinicService.savePet(currentPet);
230	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
231	            }
232	        }
233	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
234	    }
235	
236	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
237	    @Override
238	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
239	        HttpHeaders headers = new HttpHeaders();
240	        Visit visit = visitMapper.toVisit(visitFieldsDto);
241	        Pet pet = new Pet();
242	        pet.setId(petId);
243	        visit.setPet(pet);
244	        this.clinicService.saveVisit(visit);
245	        VisitDto visitDto = visitMapper.toVisitDto(visit);
246	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
247	            .buildAndExpand(visit.getId()).toUri());
248	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
249	    }
250	
251	
252	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
253	    @Override
254	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
255	        Owner owner = this.clinicService.findOwnerById(ownerId);
256	        if (owner != null) {
257	            Pet pet = owner.getPet(petId);
258	            if (pet != null) {
259	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
260	            }
261	        }
262	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
263	    }
264	
265	    private static boolean isBlank(String value) {
266	        return value == null || value.isBlank();
267	    }
268	
269	    /**
270	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
271	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
272	     * lower-cased so that last names and addresses are compared case-insensitively.
273	     */
274	    private static String normalizeHousehold(String value) {
275	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
276	    }
277	
278	    /**
279	     * Builds the {@code customerCode} assigned to a new owner, formatted
280	     * {@code '<LAST3>-<NNNN>'}: {@code LAST3} is the upper-cased first three letters of the
281	     * owner's last name, and {@code NNNN} is a global 4-digit zero-padded sequence equal to
282	     * one more than the current number of owners (e.g. {@code 'SMI-0007'}).
283	     */
284	    private String nextCustomerCode(String lastName) {
285	        String letters = lastName == null ? "" : lastName.replaceAll("[^\\p{L}]", "");
286	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
287	        long sequence = this.clinicService.findAllOwners().size() + 1L;
288	        return String.format("%s-%04d", last3, sequence);
289	    }
290	
291	    /**
292	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
293	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
294	     * national one, a single leading {@code '0'} is dropped, and the default country code
295	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'},
296	     * otherwise an {@link InvalidTelephoneException} is raised (reported to the client as 400).
297	     */
298	    private static String toE164(String telephone) {
299	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
300	        String digits;
301	        if (cleaned.startsWith("+")) {
302	            digits = cleaned.substring(1);
303	        } else {
304	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
305	            digits = "61" + national;
306	        }
307	        if (!digits.matches("[0-9]{8,15}")) {
308	            throw new InvalidTelephoneException(
309	                "telephone must form a valid E.164 number with 8 to 15 digits");
310	        }
311	        return "+" + digits;
312	    }
313	
314	    /**
315	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
316	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
317	     * is raised (reported to the client as 400). A valid value is returned lower-cased so it is
318	     * stored and returned in canonical form.
319	     */
320	    private static String normalizeEmail(String email) {
321	        if (isBlank(email)) {
322	            return null;
323	        }
324	        String trimmed = email.trim();
325	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
326	            throw new InvalidEmailException("email must be a syntactically valid address");
327	        }
328	        return trimmed.toLowerCase(Locale.ROOT);
329	    }
330	}
